public partial class Report_ViewMixParlayResult : System.Web.UI.Page
{
    public static string _sportType = String.Empty;

    protected void Page_Load(object sender, EventArgs e)
    {
        long refno = CastAide.AsInt64(Page.Request.QueryString["refno"], -1);
        int matchid = CastAide.AsInt32(Request.QueryString["matchid"], 0);
        int bettype = CastAide.AsInt32(Request.QueryString["bettype"], 0);
        string betid = CastAide.AsString(Request.QueryString["betid"]);
        try
        {
            this.lMPResult.Text = GenHTMLMixParlayResult(refno, matchid, bettype, betid);
        }
        catch (Exception ex)
        {
            Sunplus.Accounting.Core.Extensions.LogExtensions.ExceptionHandler(ex);
            this.lMPResult.Text = ex.Message;
        }
    }

    private string GenHTMLMixParlayResult(long refno, int matchid, int bettype, string betid)
    {
        string main = String.Empty;
        if (refno >= 0)
        {
            string content = String.Empty;

            DbResult dbResult = Sunplus.Accounting.DataAccess.IBCDLL.Accounting.Betlist.BetList_SelMatchResultParlay(refno.ToString());
            DataTable tblMatches = null;
            if (dbResult.ResultSet.Tables.Count > 0)
                tblMatches = dbResult.ResultSet.Tables[0];

            if (tblMatches != null && tblMatches.Rows.Count > 0)
            {
                BetListMain betlist = new BetListMain();
                List<int> arrLeagueId = new List<int>();
                List<int> arrSporttype = new List<int>();
                foreach (DataRow match in tblMatches.Rows)
                {
                    int leagueId = CastAide.AsInt32(match["LeagueID"]);
                    if (!arrLeagueId.Contains(leagueId)) arrLeagueId.Add(leagueId);
                }
                foreach (int Id in arrLeagueId)
                {
                    DataRow[] matches = tblMatches.Select(String.Format("LeagueID={0}", Id));
                    content += GenerateLeague(matches, betlist, matchid, bettype, betid);
                    content += "<br>";
                }
                string footer = String.Format("<script>var numOfMatch={0}; var numOfLeague={1}; var refno = {2}; var rootUrl = '{3}';</script>", tblMatches.Rows.Count, arrLeagueId.Count, refno.ToString(), VirtualPathUtility.ToAbsolute("~/"));
                main = String.Format("<table align='center' cellpadding='0' cellspacing='0' border='0'><tr><td>{0}</td></tr><tr><td>{1}</td></tr></table>",
                                     content, footer);
            }
            else
            {
                main = String.Format("<center>{0}</center>", Resources.Language.thereisnodata);
            }
        }
        else
        {
            main = String.Format("<center>{0}</center>", Resources.Language.thereisnodata);
        }
        return main;
    }

    private string GenerateLeague(DataRow[] matches, BetListMain betlist, int matchid, int bettype, string betid)
    {
        if (matches.Length == 0) return String.Empty;
        string templateGame = String.Empty;
        string rowTemplate = String.Empty, rowCollection = String.Empty;
        StringBuilder tempbuild = new StringBuilder();
        int sporttype = CastAide.AsInt32(matches[0]["sporttype"]);
        string beginDiv = "<div style='float:left;margin-bottom:5px;'>";
        string endDiv = "</div>";
       switch (sporttype)
       {
            case 1: //soccer
                _sportType = Resources.Language.Soccer;
                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Soccer.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderSoccer(ref templateGame, matches[0], _sportType);
                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    match["goalrecord"] = String.Empty; //not display goalrecord
                    bool isExistFGLG = CastAide.AsString(match["betstatus"] + string.Empty).Contains("FL") || CastAide.AsString(match["betstatus"] + string.Empty).Contains("1FL");
                    betlist.FillDataForSoccer(ref row, match, isExistFGLG);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 2: //basket ball
            case 3: //foot ball
            case 26: //rugby
                if (sporttype == 2)
                    _sportType = Resources.Language.Basketball;
                else if (sporttype == 3)
                    _sportType = Resources.Language.lblFootball;
                else if (sporttype == 26)
                    _sportType = Resources.Language.rugby;

                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Basketball.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderBasketBall(ref templateGame, matches[0], _sportType);
                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForBasketBall(ref row, 4, match);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 4: //ice hockey
            case 28: //field hockey
                if (sporttype == 4)
                    _sportType = Resources.Language.iceHockey;
                else if (sporttype == 28)
                    _sportType = Resources.Language.fieldHockey;

                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Hockey.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderHockey(ref templateGame, matches[0], _sportType);

                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataHocKey(ref row, match);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 5: //tennis
                break;
                _sportType = Resources.Language.lblTennis;
                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Tennis.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderTennis(ref templateGame, matches[0], _sportType);
                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForTennis(ref row, 5, match, matchid, bettype, betid);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                TemplateHandler.Assign(ref templateGame, "{setCss}", "hidden");
                TemplateHandler.Assign(ref templateGame, "{contenttblSet}", string.Empty);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 7: // Billiard
            case 10: // Golf
            case 11: // Motorsports
            case 29: // Winter sports
            case 43: // E-Sports
                if (sporttype == 7)
                    _sportType = Resources.Language.billiard;
                else if (sporttype == 10)
                    _sportType = Resources.Language.lblGolf;
                else if (sporttype == 11)
                    _sportType = Resources.Language.lblMotosports;
                else if (sporttype == 29)
                    _sportType = Resources.Language.winterSports;
                else if (sporttype == 43)
                    _sportType = Resources.Language.ESports;

                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Billiard.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");

                betlist.FillHeaderBillard(ref templateGame, matches[0], _sportType);
                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForBillard(ref row, match);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 8: //baseball
                _sportType = Resources.Language.lblBaseball;
                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Baseball.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderBaseball(ref templateGame, matches[0], _sportType);
                rowCollection = String.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForBaseball(ref row, 9, match);
                    rowCollection += row;
                }
                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            case 6: //volleyball
            case 9: //badminton
            case 30: //squash
                if (sporttype == 6)
                    _sportType = Resources.Language.volleyBall;
                else if (sporttype == 9)
                    _sportType = Resources.Language.badminton;
                else if (sporttype == 30)
                    _sportType = Resources.Language.squash;

                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Badminton.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderBadminton(ref templateGame, matches[0], _sportType);
                rowCollection = string.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForBadminton(ref row, match);
