                TemplateHandler.ReplaceBlock(ref templateGame, "row", rowCollection);
                templateGame = beginDiv + templateGame + endDiv;
                tempbuild.Append(templateGame);
                break;

            default:
                templateGame = Sunplus.Accounting.Core.Web.WebUtils.LoadTemplate("BetList/Common.htm");
                rowTemplate = TemplateHandler.CopyBlock(templateGame, "row");
                betlist.FillHeaderCommon(ref templateGame, matches[0]);
                rowCollection = string.Empty;
                foreach (DataRow match in matches)
                {
                    string row = rowTemplate;
                    betlist.FillDataForCommon(ref row, match);
